  ('e1453769-4307-5f59-b67a-cc8fc50489fb', null, (select id from public.skills where slug = 'read-g11-story-details-inference'), null, 'medium',
   $q$Why does Brisk first decide that the fox is a fraud?$q$, $q$[{"text":"The fox refuses to answer when she asks about the price.","is_correct":false,"misconception_token":"contradicts-text"},{"text":"She sees the fox keeping the acorns instead of using them.","is_correct":false,"misconception_token":"unsupported-inference"},{"text":"The canyon returns her shout more softly than it does for others.","is_correct":false,"misconception_token":"contradicts-text"},{"text":"Her free shout beyond the line echoes just as the paid ones do.","is_correct":true}]$q$::jsonb, $q$Her free shout beyond the line echoes just as the paid ones do.$q$, $q$The canyon sends her name back "exactly as it did for everyone else," which shows the echo does not depend on paying. The text says nothing about how the fox uses the acorns at this point.$q$, 'draft', '6ca79473-7f0b-539b-8f69-1fa6e082c138')
